command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: KALTES STARREN (Ausführung)
// ==========================================

(async () => {
    // --- 1. FRAMEWORK LADEN ---
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined") return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    const gabenName = "Kaltes Starren";
    const ahne = "Rondra";
    const finalEffektName = `${gabenName} (${ahne})`;
    const iconBild = DSK_FW.Symbol(ahne);

    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register("rondraKaltesStarren", finalEffektName, "Der eisige Blick des Rondrakindes normalisiert sich wieder.");
    }

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    // --- 2. CASTER & QS ERMITTELN ---
    let safeTestData = typeof testData !== "undefined" ? testData : null;
    let safeActor = typeof actor !== "undefined" ? actor : null;

    let casterActor = safeTestData?.actor || (safeTestData?.speaker?.token ? canvas.tokens.get(safeTestData.speaker.token)?.actor : null) || safeActor;
    if (!casterActor) casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;

    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) {
                casterActor = t.actor; break;
            }
        }
    }

    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    let whisperTargets = [...new Set([...game.users.filter(u => u.isGM).map(u => u.id), ...getOwners(casterActor)])].filter(id => game.users.get(id));

    const qsWert = Number(safeTestData?.result?.QL || safeTestData?.qualityStep || casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");

    if (qsWert <= 0) {
        return ChatMessage.create({
            whisper: whisperTargets, speaker: { alias: "System" },
            content: `${DSK_FW.UI.Header(gabenName, iconBild)}<div class="dskbox2"><p style="color:#B30000;text-align:center;"><b>Fehlschlag!</b></p></div>`
        });
    }

    // --- 3. BERECHNUNGEN ---
    const dauerKR = qsWert * 4;
    const reichweite = 8;
    const furchtStufen = qsWert;

    await casterActor.unsetFlag("world", "letzteGabenQS");
    await casterActor.unsetFlag("world", "letzteGabenMessageId");

    let alterEffekt = casterActor.effects.find(e => (e.name || e.label) === finalEffektName);
    if (alterEffekt) await alterEffekt.delete();

    // --- 4. EFFEKT AUF DEN WIRKENDEN (CASTER) ---
    await casterActor.createEmbeddedDocuments("ActiveEffect", [{
        name: finalEffektName,
        icon: iconBild,
        img: iconBild,
        duration: { rounds: dauerKR },
        description: `Der Blick des Rondrakindes ist kalt wie Eis. Das erste Ziel (Erwachte/Tiere) innerhalb von 8 Schritt, das für 1 Aktion angestarrt wird, erleidet ${furchtStufen} Stufen Status Furcht.`,
        flags: { dsk: { ahne: ahne } }
    }]);

    const casterName = DSK_FW.ResolveTokenName(casterActor);
    const casterUuid = casterActor.uuid;

    // --- 5. AUTOMATISCHER KETTEN-AUFLÖSER ---
    if (!globalThis.DSK_KaltesStarrenCleanup) {
        globalThis.DSK_KaltesStarrenCleanup = true;
        Hooks.on("deleteActiveEffect", async (effect) => {
            if (!game.user.isGM) return;
            const parentUuid = effect.parent?.uuid; 
            if (!parentUuid) return;

            if ((effect.name || effect.label) === finalEffektName) {
                for (let t of canvas.tokens.placeables) {
                    if (t.actor) {
                        let linkedEffekte = t.actor.effects.filter(e => e.getFlag("dsk", "parentCasterUuid") === parentUuid);
                        for (let le of linkedEffekte) {
                            await le.delete();
                        }
                    }
                }
            }
        });
    }

    // --- 6. GLOBALER CHAT-LISTENER FÜR DEN BUTTON ---
    if (!globalThis.DSK_KaltesStarrenHook) {
        globalThis.DSK_KaltesStarrenHook = true;
        Hooks.on("renderChatMessage", (msg, html) => {
            html.find('.kaltes-starren-btn').click(async (ev) => {
                ev.preventDefault();
                if (!game.user.isGM) return ui.notifications.warn("Luna sagt 🌙: Nur der Meister kann den Furcht-Effekt anwenden.");

                const btn = ev.currentTarget;
                if (btn.disabled) return; 

                const qs = Number(btn.dataset.qs) || 1;
                const dauer = Number(btn.dataset.dauer) || 1; 
                const nameWirkender = btn.dataset.castername;
                const gabenIcon = btn.dataset.icon; 
                const buttonCasterUuid = btn.dataset.casteruuid;
                const messageId = btn.closest(".message").dataset.messageId;

                const targets = Array.from(game.user.targets);
                if (targets.length === 0) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst ein Ziel per Target aus!");
                const targetActor = targets[0].actor;

                // 🚩 STRENGE PRÜFUNG: Ist es ein Erwachter oder Tier?
                if (!DSK_FW.Wesen.match(targetActor, ["erwacht", "erwachter", "erwachte", "tier", "tiere"])) {
                    // NEIN: Flüsternachricht an den Spieler/GM im schönen DSK Layout!
                    let cActor = await fromUuid(buttonCasterUuid);
                    if (cActor && cActor.actor) cActor = cActor.actor;

                    let whisperTo = game.users.filter(u => u.isGM).map(u => u.id);
                    if (cActor) {
                        const owners = Object.entries(cActor.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);
                        whisperTo = [...new Set([...whisperTo, ...owners])].filter(id => game.users.get(id));
                    }

                    // Das edle Fehler-Layout "Information"
                    const infoHtml = `
                        <div style="font-family: 'Signika', sans-serif;">
                            <div class="dskbox1">
                                <p style="display:flex; gap:8px; align-items:center; margin:0;">
                                    <img src="${gabenIcon}" style="width:28px; border:none; background:transparent;">
                                    <b style="font-size: 1.05em;">Information</b>
                                </p>
                                <p style="font-weight:bold; margin-top:6px; margin-bottom:0;">${finalEffektName}</p>
                            </div>
                            <div class="dskbox2" style="margin-top:10px; text-align: center;">
                                <p style="margin-bottom: 8px;"><b>${targetActor.name}</b> ist weder ein Erwachter noch ein Tier.</p>
                                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                                <p style="margin-bottom: 8px; color: #8b0000;"><b>Fehlschlag!</b> Der Fluch konnte nicht angewendet werden.</p>
                                <p style="margin-bottom: 8px;">Du darfst stattdessen für die restliche Wirkungsdauer ein anderes Ziel anstarren!</p>
                            </div>
                        </div>
                    `;

                    await ChatMessage.create({
                        whisper: whisperTo,
                        speaker: { alias: "System" },
                        content: infoHtml
                    });
                    return; // Button bleibt funktionsfähig!
                }

                // 🚩 JA: FURCHT ANWENDEN
                const targetEffektName = `Kaltes Starren (Rondra) - Furcht - (${nameWirkender})`;
                let existing = targetActor.effects.find(e => (e.name || e.label) === targetEffektName);
                if (existing) await existing.delete();

                await targetActor.createEmbeddedDocuments("ActiveEffect", [{
                    name: targetEffektName,
                    type: "base",
                    icon: gabenIcon,
                    img: gabenIcon,
                    duration: { rounds: dauer },
                    description: `Wird vom eisigen Blick von ${nameWirkender} angestarrt.`,
                    changes: [{ key: "system.status.feared", mode: 2, value: String(qs), priority: 20 }],
                    statuses: ["feared"],
                    flags: { 
                        core: { statusId: "feared" },
                        dsk: { parentCasterUuid: buttonCasterUuid } 
                    }
                }]);

                ui.notifications.info(`Luna sagt 🌙: ${qs} Stufen Furcht auf ${targetActor.name} angewendet.`);

                // CHATKARTE UPDATEN: Button ausgrauen
                const chatMsg = game.messages.get(messageId);
                if (chatMsg) {
                    const tempDiv = document.createElement("div");
                    tempDiv.innerHTML = chatMsg.content;
                    const btnInMsg = tempDiv.querySelector('.kaltes-starren-btn');

                    if (btnInMsg) {
                        const newBtnHtml = `
                            <button disabled style="background:#4a4a4a; color:#999; border:1px solid #222; border-radius:4px; font-weight:bold; padding:4px 8px; font-size:12px; width:100%; cursor:not-allowed;">
                                <i class="fas fa-check" style="margin-right: 4px;"></i> Furcht angewendet
                            </button>
                            <p style="margin-top: 6px; font-size: 0.95em; color: #18940F; font-weight: bold;">
                                ✓ Angewendet auf: ${targetActor.name}
                            </p>
                        `;
                        btnInMsg.parentElement.innerHTML = newBtnHtml;
                        await chatMsg.update({ content: tempDiv.innerHTML });
                    }
                }
            });
        });
    }

    // --- 7. CHAT NACHRICHT GENERIEREN ---
    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';

    const successContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p>Der Blick von <b>${casterName}</b> wird kalt wie Eis.</p>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="margin-bottom: 8px;">
                    Das erste Ziel <i>(Erwachte und Tiere)</i> innerhalb von <b>${reichweite} Schritt</b>, das für mindestens eine Aktion angestarrt wird, erleidet <b>${furchtStufen} Stufe(n) Status Furcht</b>.
                </p>
                <p style="font-size: 0.85em; color: #555;"><i>Der Zustand bleibt bis zum Ende der Wirkungsdauer bestehen.</i></p>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="text-align:center; font-weight:bold;">Wirkungsdauer:<br>${dauerKR} Kampfrunden <span ${thinStyle}>(${qsWert} QS x 4)</span></p>

                <div style="text-align:center; margin-top: 10px;">
                    <button class="kaltes-starren-btn" data-qs="${qsWert}" data-dauer="${dauerKR}" data-castername="${casterName}" data-icon="${iconBild}" data-casteruuid="${casterUuid}" style="background:linear-gradient(#76301b,#582617); color:#f8f6f5; border:1px solid #000; border-radius:4px; font-weight:bold; padding:4px 8px; font-size:12px; cursor:pointer; width:100%;">
                        <i class="fas fa-eye" style="margin-right: 4px;"></i> Furcht anwenden
                    </button>
                </div>
            </div>
        </div>
    `;

    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        await msg.update({ content: successContent, whisper: whisperTargets });
    } else {
        await ChatMessage.create({ whisper: whisperTargets, content: successContent, speaker: { alias: "System" } });
    }
})();
